      const u4 = new Bot({ server: 'ws://127.0.0.1:1', room: 'x', pass: 'x', name: 'U4', log: () => {} });
      u4._huntingGroundUsedThisTurn = false;
      const pap = { id: 'p1', name: 'Papillon', kind: 'lib', zone: 'ready', locked: false };
