  /* 93c) LUNGE: the prey within what my bodies can land -- home 0, keep-a-blocker yields, even for a grinding deck */
  const c = mk93({ deckName: 'tremere' }); c.board = [body('m1', 'Lauren'), body('m2', 'Nassir'), body('m3', 'Chrysanthemum')]; c.hand = [];
