  const c2 = mk93({ deckName: 'tremere' }); c2.board = [body('m1', 'Lauren'), body('m2', 'Nassir'), body('m3', 'Chrysanthemum')]; c2.hand = [];
  c2._onBoard({ seat: 3, pub: pub93([], 3) });
