  /* the mirror: same swarm, but I am healthy and the prey is thin -> race, nobody home (a non-grinding deck) */
  const f2 = mk93(); f2.pool = 28; f2.board = [body('m1', 'Lauren'), body('m2', 'Nassir'), body('m3', 'Chrysanthemum')]; f2.hand = [];
