  /* the grinding quota stays as the floor of home */
  const f3 = mk93({ deckName: 'tremere' }); f3.pool = 28; f3.board = [body('m1', 'Lauren'), body('m2', 'Nassir'), body('m3', 'Chrysanthemum')]; f3.hand = [];
