  const j = mk93({ deckName: 'nosferatu' }); j.pool = 6; j.board = [body('m1', 'Lenny Burkhead (G6)'), body('m2', 'Larissa Moreira (G6)'), body('m3', 'Wauneka (G6)')]; j.hand = [];
