          u.seat = seat; u.started = true; u.players = P.map(p => Object.assign({}, p)); u.push = () => {}; u.fxClone = () => {}; u.lines = []; u.evs = [];
          u.onEvent = (t, m) => { if(t === 'bot:probe-order' || t === 'bot:probe-hold') u.evs.push({ t, m }); };
